import React from "react";
import headerBg from '../img/header-bg.png'; 

const Home = () => {
  return (
    <div style={{ position: "relative", minHeight: "100vh" }}>
      
      {/* Верхний правый угол */}
      <div style={{
        position: "absolute",
        top: "20px",
        right: "20px",
        display: "flex",
        gap: "15px"
      }}>
        <a href="#projects" style={{ textDecoration: "none", color: "black", fontWeight: "bold" }}>Projects</a>
        <a href="#contacts" style={{ textDecoration: "none", color: "black", fontWeight: "bold" }}>Contacts</a>
      </div>

      {/* Центр страницы */}
      <div
        style={{
          border: '1px solid black',
          width: '1400px',
          height: '400px',
          textAlign: "center",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: "20px",        
          padding: "20px",
          margin: "0 auto", // центр по горизонтали
          marginTop: "80px" // чтобы не перекрывало верхние ссылки
        }}
      >
        <h1>Hi, my name is <strong>John Doe</strong></h1>
        <h2>a frontend developer</h2>
        <h3>with passion for learning and creating.</h3>

        <img
          src={headerBg} 
          alt="Profile"
          style={{ width: "200px", borderRadius: "50%" }}
        />

        <a href="CV.pdf" download>
          <button
            style={{
              padding: "10px 20px",
              fontSize: "16px",
              cursor: "pointer",
              borderRadius: "5px",
              backgroundColor: "#4CAF50",
              color: "white",
              border: "none",
            }}
          >
            Download CV
          </button>
        </a>
      </div>
    </div>
  );
};

export default Home;
